import { test, expect } from '@playwright/test';

test.describe('Modal Dialog', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-application-url.com');
    await page.getByText('Open Modal').click();
  });

  test('should close the modal when clicking the backdrop', async ({ page }) => {
    const modal = page.getByRole('dialog');
    const backdrop = page.getByRole('presentation');

    await expect(modal).toBeVisible();
    await backdrop.click();
    await expect(modal).not.toBeVisible();
  });

  test('should not close the modal when clicking inside the modal', async ({ page }) => {
    const modal = page.getByRole('dialog');
    const modalContent = modal.getByText('Modal Content');

    await expect(modal).toBeVisible();
    await modalContent.click();
    await expect(modal).toBeVisible();
  });
});
